const fs=require('fs');
const crypto=require('crypto');
const input=$json;
if(!input.content_id||Number(input.version)!==1)throw new Error('Conteudo ou v1 nao encontrado para render inicial.');
if(!input.template_id)throw new Error('Cliente sem default_template_id configurado.');
if(!input.generated_image_path)throw new Error('Imagem fonte nao persistida.');
const dataPath=p=>'/data/'+String(p).replace(/^\/+/, '');
const sourcePath=dataPath(input.generated_image_path);
if(!fs.existsSync(sourcePath)||fs.statSync(sourcePath).size===0)throw new Error('Imagem fonte ausente ou vazia.');
const safeClient=String(input.client_id).replace(/[^a-zA-Z0-9_-]/g,'-');
const outputPath='assets/generated/'+safeClient+'/'+input.content_id+'/rendered/final-v1.png';
const layoutPath='assets/generated/'+safeClient+'/'+input.content_id+'/specs/layout-v1.json';
const outputFile=dataPath(outputPath),layoutFile=dataPath(layoutPath);
const artifactsExist=fs.existsSync(outputFile)&&fs.statSync(outputFile).size>0&&fs.existsSync(layoutFile)&&fs.statSync(layoutFile).size>0;
let recoveredLayout=null,recoveredChecksum=null;
if(artifactsExist){recoveredLayout=JSON.parse(fs.readFileSync(layoutFile,'utf8'));recoveredChecksum=crypto.createHash('sha256').update(fs.readFileSync(outputFile)).digest('hex').toUpperCase();}
return [{json:{...input,output_path:outputPath,layout_spec_path:layoutPath,artifacts_exist:artifactsExist,recovered_layout:recoveredLayout,recovered_checksum:recoveredChecksum}}];
